---
export const freeComponent = true;
import Text from "@/components/fundations/typography/Text.astro";
const stats = [
  {
    label: "Working Individuals",
    value: "30%",
  },
  {
    label: "Super low fee",
    value: "40%",
  },
  {
    label: "Great Commitment",
    value: "50%",
  },
  {
    label: "Massive Earnings",
    value: "60M",
  },
];
---

<section class="bg-white ">
  <div
    class="flex items-center justify-center px-8 py-24 mx-auto max-w-7xl md:px-12 lg:px-20"
  >
    <div class="flex flex-wrap justify-center text-center gap-x-8 gap-y-2">
      {
        stats.map((stat) => (
          <div class="flex items-baseline gap-2 ">
            <Text
              tag="p"
              variant="textBase"
              class="font-medium text-primary/88 "
            >
              {stat.value}
            </Text>
            <Text
              tag="h3"
              variant="textBase"
              class="font-medium text-base-900 "
            >
              {stat.label}
            </Text>
          </div>
        ))
      }
    </div>
  </div>
</section>
